//! Mutated inputs and their judgments (`skein/docs/design/testing/checks.md`, 1).

/// An input carrying the number of generated mutations it represents.
#[must_use]
pub struct Mutation<T> {
    input: T,
    count: u64,
}

/// Mark an input generated by a mutation helper.
pub const fn mutation<T>(input: T) -> Mutation<T> {
    Mutation { input, count: 1 }
}

impl<T> From<T> for Mutation<T> {
    /// Carry an unmutated input through the same judge.
    fn from(input: T) -> Self {
        Self { input, count: 0 }
    }
}

impl<T> Mutation<T> {
    /// Borrow the input to prepare its judgment.
    pub const fn input(&self) -> &T {
        &self.input
    }

    /// Carry the count with the input into a fixture that uses it.
    pub fn map<U>(self, prepare: impl FnOnce(T) -> U) -> Mutation<U> {
        Mutation { input: prepare(self.input), count: self.count }
    }

    /// Combine inputs that the same operation judges together.
    pub fn zip<U>(self, other: Mutation<U>) -> Mutation<(T, U)> {
        Mutation {
            input: (self.input, other.input),
            count: self.count.checked_add(other.count).expect("combined mutations fit u64"),
        }
    }

    /// Record the mutations after the judge returns.
    pub fn judge<R>(self, check: impl FnOnce(T) -> R) -> R {
        let mut batch = MutationBatch::default();
        let verdict = batch.judge(self, check);
        batch.finish();
        verdict
    }
}

/// Counts judgments in a loop and appends their sum once.
#[derive(Default)]
#[must_use]
pub struct MutationBatch {
    judged: u64,
}

impl MutationBatch {
    /// Run the judge and tally the mutations it received.
    pub fn judge<T, R>(&mut self, mutation: Mutation<T>, check: impl FnOnce(T) -> R) -> R {
        let verdict = check(mutation.input);
        self.judged = self.judged.checked_add(mutation.count).expect("mutation judgments fit u64");
        verdict
    }

    /// Append the total if the batch judged any mutations.
    pub fn finish(self) {
        if self.judged > 0 {
            crate::count("mutation", self.judged);
        }
    }
}
